import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as plt_sns
import seaborn as sns
import base64
from io import BytesIO
from jinja2 import Environment, FileSystemLoader, Template
import os

sns.set_theme(style="whitegrid")

def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')
df['date'] = pd.to_datetime(df['date'])
df['year'] = df['date'].dt.year
df['month'] = df['date'].dt.month
df['day_of_week'] = df['date'].dt.day_name()
df['is_workout'] = df['workout_type'] != 'None'

# Fix workout duration where workout is None
df.loc[df['workout_type'] == 'None', 'workout_duration_minutes'] = 0

# Unique users for demographics
users_df = df.sort_values('date').drop_duplicates('user_id', keep='last')

plots = {}

# Section 1: Demographics
fig, axes = plt.subplots(1, 2, figsize=(10, 4))
sns.histplot(users_df['age'], bins=15, ax=axes[0], kde=True, color='skyblue')
axes[0].set_title('Age Distribution')
axes[0].set_xlabel('Age')
axes[0].set_ylabel('Count')

gender_counts = users_df['gender'].value_counts()
axes[1].pie(gender_counts, labels=gender_counts.index, autopct='%1.1f%%', colors=['#ff9999','#66b3ff'])
axes[1].set_title('Gender Distribution')
plots['demographics'] = fig_to_base64(fig)

# Section 2: Activity
fig, ax = plt.subplots(figsize=(8, 4))
sns.barplot(data=df[df['workout_type'] != 'None'], x='workout_type', y='workout_duration_minutes', hue='gender', ax=ax)
ax.set_title('Average Workout Duration by Type and Gender')
ax.set_xlabel('Workout Type')
ax.set_ylabel('Minutes')
plots['activity_duration'] = fig_to_base64(fig)

fig, ax = plt.subplots(figsize=(8, 4))
sns.boxplot(data=df, x='workout_type', y='steps', ax=ax, palette='Set2')
ax.set_title('Steps by Workout Type')
ax.set_xlabel('Workout Type')
ax.set_ylabel('Daily Steps')
plots['activity_steps'] = fig_to_base64(fig)

# Section 3: Vitals
fig, axes = plt.subplots(1, 2, figsize=(12, 4))
sns.scatterplot(data=df, x='sleep_hours', y='heart_rate_avg', hue='stress_level', palette='coolwarm', ax=axes[0])
axes[0].set_title('Sleep vs Heart Rate (Colored by Stress)')
axes[0].set_xlabel('Sleep Hours')
axes[0].set_ylabel('Avg Heart Rate')

sns.barplot(data=df, x='workout_type', y='calories_burned', ax=axes[1], palette='magma')
axes[1].set_title('Calories Burned by Workout Type')
axes[1].set_xlabel('Workout Type')
axes[1].set_ylabel('Calories Burned')
plots['vitals'] = fig_to_base64(fig)

# Section 4: Lifestyle
fig, axes = plt.subplots(1, 2, figsize=(12, 4))
sns.barplot(data=df, x='mood', y='stress_level', palette='pastel', ax=axes[0])
axes[0].set_title('Average Stress Level by Mood')
axes[0].set_xlabel('Mood')
axes[0].set_ylabel('Stress Level')

sns.violinplot(data=df, x='mood', y='steps', palette='muted', ax=axes[1])
axes[1].set_title('Daily Steps by Mood')
axes[1].set_xlabel('Mood')
axes[1].set_ylabel('Daily Steps')
plots['lifestyle'] = fig_to_base64(fig)

# Section 5: Temporal Trends (Highest Priority)
fig, axes = plt.subplots(3, 1, figsize=(12, 12))
# Yearly Trends
yearly_steps = df.groupby('year')['steps'].mean().reset_index()
sns.lineplot(data=yearly_steps, x='year', y='steps', ax=axes[0], marker='o', linewidth=2.5)
axes[0].set_title('Year-over-Year Average Daily Steps')
axes[0].set_xlabel('Year')
axes[0].set_ylabel('Avg Steps')
axes[0].set_xticks(yearly_steps['year'])

# Monthly Seasonal Trends
monthly_workout = df.groupby('month')['is_workout'].mean().reset_index()
sns.barplot(data=monthly_workout, x='month', y='is_workout', ax=axes[1], color='coral')
axes[1].set_title('Seasonal Workout Participation Rate by Month')
axes[1].set_xlabel('Month (1-12)')
axes[1].set_ylabel('Participation Rate')

# Day of Week Trends
dow_order = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
dow_steps = df.groupby('day_of_week')['steps'].mean().reindex(dow_order).reset_index()
sns.barplot(data=dow_steps, x='day_of_week', y='steps', ax=axes[2], palette='viridis')
axes[2].set_title('Average Steps by Day of Week')
axes[2].set_xlabel('Day of Week')
axes[2].set_ylabel('Avg Steps')

plt.tight_layout()
plots['temporal'] = fig_to_base64(fig)

# Compute KPIs
kpis = {
    'avg_daily_steps': f"{df['steps'].mean():.0f}",
    'avg_calories': f"{df['calories_burned'].mean():.0f}",
    'avg_sleep': f"{df['sleep_hours'].mean():.1f}",
    'workout_participation': f"{(df['is_workout'].mean() * 100):.1f}%",
    'avg_stress': f"{df['stress_level'].mean():.1f}"
}

# Advanced metrics for text
participation_by_gender = df.groupby('gender')['is_workout'].mean() * 100
highest_participation_gender = participation_by_gender.idxmax()

avg_steps_by_mood = df.groupby('mood')['steps'].mean()
best_mood_steps = avg_steps_by_mood.idxmax()

monthly_part = df.groupby('month')['is_workout'].mean()
best_month = monthly_part.idxmax()

yearly_trend_start = df[df['year'] == df['year'].min()]['steps'].mean()
yearly_trend_end = df[df['year'] == df['year'].max()]['steps'].mean()
trend_dir = "increased" if yearly_trend_end > yearly_trend_start else "decreased"

